```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    m1: Mutex<()>,
    m2: Mutex<()>,
    cv: Condvar,
    announced: Mutex<i32>,
    done: Mutex<i32>,
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(()),
        m2: Mutex::new(()),
        cv: Condvar::new(),
        announced: Mutex::new(0),
        done: Mutex::new(0),
    });

    let s1 = Arc::clone(&shared);
    let h1 = thread::spawn(move || waiter1(s1));

    let s2 = Arc::clone(&shared);
    let h2 = thread::spawn(move || waiter2(s2));

    let s3 = Arc::clone(&shared);
    let h3 = thread::spawn(move || notifier(s3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    let done = *shared.done.lock().unwrap();
    println!("DONE done={}", done);
}

fn waiter1(shared: Arc<Shared>) {
    let guard1 = shared.m1.lock().unwrap();

    {
        let mut a = shared.announced.lock().unwrap();
        let a2 = *a + 1;
        *a = a2;
    }

    let guard1 = shared.cv.wait(guard1).unwrap();

    {
        let mut d = shared.done.lock().unwrap();
        let d2 = *d + 1;
        *d = d2;
    }

    drop(guard1);
}

fn waiter2(shared: Arc<Shared>) {
    let guard2 = shared.m2.lock().unwrap();

    {
        let guard1 = shared.m1.lock().unwrap();
        let mut a = shared.announced.lock().unwrap();
        let a2 = *a + 1;
        *a = a2;
        drop(a);
        drop(guard1);
    }

    let guard2 = shared.cv.wait(guard2).unwrap();

    {
        let guard1 = shared.m1.lock().unwrap();
        let mut d = shared.done.lock().unwrap();
        let d2 = *d + 1;
        *d = d2;
        drop(d);
        drop(guard1);
    }

    drop(guard2);
}

fn notifier(shared: Arc<Shared>) {
    let guard1 = shared.m1.lock().unwrap();

    loop {
        let a = shared.announced.lock().unwrap();
        let ready = *a == 2;
        drop(a);
        if ready {
            break;
        }
        thread::yield_now();
    }

    let guard2 = shared.m2.lock().unwrap();

    shared.cv.notify_all();

    drop(guard2);
    drop(guard1);
}
